const cfg=window.APP_CONFIG||{};
const configured=cfg.SUPABASE_URL?.startsWith('https://')&&!cfg.SUPABASE_URL.includes('PASTE_')&&cfg.SUPABASE_ANON_KEY&&!cfg.SUPABASE_ANON_KEY.includes('PASTE_');
const sb=configured?window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY):null;
const state={user:null,profile:null,settings:{store_name:'Shoes Store'},products:[],variants:[],sales:[],expenses:[],suppliers:[],purchases:[],customers:[],shifts:[],movements:[],returns:[],audit:[],cart:[],purchaseCart:[],charts:[],current:'dashboard'};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n||0));
const todayISO=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'}); const esc=(v='')=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const num=n=>Number(n||0); const dateId=d=>new Date(d).toLocaleString('id-ID',{timeZone:'Asia/Jakarta',dateStyle:'short',timeStyle:'short'});
function toast(msg){const e=document.createElement('div');e.className='toast';e.textContent=msg;$('#toast').appendChild(e);setTimeout(()=>e.remove(),3500)}
function metric(label,value,hint='',cls=''){return `<div class="card metric"><div class="label">${label}</div><div class="value ${cls}">${value}</div><div class="hint">${hint}</div></div>`}
async function audit(action,entity,id,details={}){try{await sb.rpc('write_audit',{p_action:action,p_entity:entity,p_entity_id:String(id||''),p_details:details})}catch{}}

async function init(){
 $('#connectionInfo').textContent=configured?'Database cloud siap. Login untuk memulai.':'Belum terhubung Supabase. Isi config.js terlebih dahulu.';
 $('#loginForm').addEventListener('submit',login);$('#logoutBtn').onclick=logout;$('#togglePassword').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password'};$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');
 $('#saleDiscount').addEventListener('input',updateCheckout);$('#paymentMethod').addEventListener('change',updateCheckout);$('#paidAmount').addEventListener('input',updateCheckout);$('#confirmCheckout').onclick=checkout;$('#printReceipt').onclick=printReceiptOnly;$('#printBarcode').onclick=printBarcodeOnly;
 setInterval(()=>$('#clock')&&($('#clock').textContent=new Date().toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})),1000);
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});let deferred;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('#installBtn').classList.remove('hidden')});$('#installBtn').onclick=async()=>{if(deferred){deferred.prompt();await deferred.userChoice;deferred=null;$('#installBtn').classList.add('hidden')}};
 if(!sb)return;const{data:{session}}=await sb.auth.getSession();if(session){state.user=session.user;await bootApp()}sb.auth.onAuthStateChange(async(e,s)=>{if(s&&!state.profile){state.user=s.user;await bootApp()}})
}
async function login(e){e.preventDefault();if(!sb)return toast('Hubungkan Supabase terlebih dahulu.');const{data,error}=await sb.auth.signInWithPassword({email:$('#email').value,password:$('#password').value});if(error)return toast(error.message);state.user=data.user;await bootApp()}
async function logout(){if(sb)await sb.auth.signOut();location.reload()}
async function bootApp(){const{data,error}=await sb.from('profiles').select('*').eq('id',state.user.id).single();if(error||!data)return toast('Profil/role user belum dibuat di tabel profiles.');if(!data.active)return toast('Akun dinonaktifkan.');state.profile=data;$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#userName').textContent=data.full_name||state.user.email;$('#userRole').textContent=data.role.toUpperCase();buildNav();await refreshAll();subscribeRealtime();route('dashboard')}
function buildNav(){const role=state.profile.role;const all={kasir:[['UTAMA'],['dashboard','Dashboard'],['pos','Kasir / POS'],['shifts','Shift Kasir'],['sales','Riwayat Penjualan']],admin:[['UTAMA'],['dashboard','Dashboard'],['pos','Kasir / POS'],['products','Produk & Stok'],['purchases','Pembelian'],['suppliers','Supplier'],['stock','Stock Opname'],['returns','Retur'],['expenses','Pengeluaran'],['sales','Penjualan'],['reports','Laporan']],owner:[['UTAMA'],['dashboard','Dashboard Owner'],['pos','Kasir / POS'],['shifts','Shift Kasir'],['MASTER & STOK'],['products','Produk & Stok'],['suppliers','Supplier'],['purchases','Pembelian'],['stock','Stock Opname'],['returns','Retur'],['KEUANGAN'],['sales','Penjualan'],['expenses','Pengeluaran'],['reports','Laporan'],['KONTROL'],['audit','Audit Log'],['settings','Pengaturan']]}[role];$('#navMenu').innerHTML=all.map(x=>x.length===1?`<div class="nav-group">${x[0]}</div>`:`<button class="nav-btn" data-route="${x[0]}">${x[1]}</button>`).join('');$$('.nav-btn').forEach(b=>b.onclick=()=>route(b.dataset.route))}
function allowed(){return {kasir:['dashboard','pos','shifts','sales'],admin:['dashboard','pos','products','purchases','suppliers','stock','returns','expenses','sales','reports'],owner:['dashboard','pos','shifts','products','purchases','suppliers','stock','returns','expenses','sales','reports','audit','settings']}[state.profile.role]}
function route(name){if(!allowed().includes(name))return;state.current=name;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.route===name));$('#sidebar').classList.remove('open');destroyCharts();({dashboard:renderDashboard,pos:renderPOS,products:renderProducts,suppliers:renderSuppliers,purchases:renderPurchases,stock:renderStock,returns:renderReturns,shifts:renderShifts,sales:renderSales,expenses:renderExpenses,reports:renderReports,audit:renderAudit,settings:renderSettings}[name]||renderDashboard)()}
function destroyCharts(){state.charts.forEach(c=>{try{c.destroy()}catch{}});state.charts=[]}
async function refreshAll(){
  const q=async(label,query,fallback)=>{
    try{const r=await query;if(r.error){console.error(label,r.error);if(label==='sales')toast('Gagal membaca data penjualan: '+(r.error.message||'cek RLS/database'));return fallback}return r.data??fallback}
    catch(e){console.error(label,e);return fallback}
  };
  state.settings=await q('settings',sb.from('settings').select('*').eq('id',1).maybeSingle(),state.settings);
  state.products=await q('products',sb.from('products').select('*,brands(name),categories(name)').order('name'),state.products);
  state.variants=await q('variants',sb.from('product_variants').select('*,products(name,sku,sale_price,cost_price,brand_id,category_id)').eq('active',true).order('size'),state.variants);

  // Jangan gunakan embedded profiles pada query sales. Jika relasi FK/permission
  // bermasalah, query sales tetap harus masuk agar omzet dan riwayat tidak menjadi Rp0.
  const sales=await q('sales',sb.from('sales').select('*').order('created_at',{ascending:false}).limit(500),state.sales);
  const cashierIds=[...new Set(sales.map(s=>s.cashier_id).filter(Boolean))];
  let profileMap={};
  if(cashierIds.length){
    const profs=await q('sales profiles',sb.from('profiles').select('id,full_name').in('id',cashierIds),[]);
    profileMap=Object.fromEntries(profs.map(p=>[p.id,p]));
  }
  state.sales=sales.map(s=>({...s,profiles:profileMap[s.cashier_id]||null}));

  state.expenses=await q('expenses',sb.from('expenses').select('*').order('expense_date',{ascending:false}).limit(500),state.expenses);
  state.customers=await q('customers',sb.from('customers').select('*').order('name'),state.customers);
  state.shifts=await q('shifts',sb.from('shifts').select('*').order('opened_at',{ascending:false}).limit(100),state.shifts);
  let i=0;
  if(state.profile.role!=='kasir'){
    state.suppliers=await q('suppliers',sb.from('suppliers').select('*').eq('active',true).order('name'),state.suppliers);
    state.purchases=await q('purchases',sb.from('purchases').select('*').order('created_at',{ascending:false}).limit(300),state.purchases);
    state.movements=await q('stock movements',sb.from('stock_movements').select('*,product_variants(size,color,products(name,sku))').order('created_at',{ascending:false}).limit(500),state.movements);
    state.returns=await q('returns',sb.from('sale_returns').select('*').order('created_at',{ascending:false}).limit(200),state.returns);
  }
  if(state.profile.role==='owner')state.audit=await q('audit',sb.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(500),state.audit);
  $('#storeNameSide').textContent=state.settings.store_name||'Shoes Store';
  $('#loginStoreName').textContent=state.settings.store_name||'Shoes Store';
}
function subscribeRealtime(){sb.channel('store-live-v2').on('postgres_changes',{event:'*',schema:'public',table:'sales'},reloadCurrent).on('postgres_changes',{event:'*',schema:'public',table:'product_variants'},reloadCurrent).on('postgres_changes',{event:'*',schema:'public',table:'expenses'},reloadCurrent).on('postgres_changes',{event:'*',schema:'public',table:'purchases'},reloadCurrent).on('postgres_changes',{event:'*',schema:'public',table:'shifts'},reloadCurrent).on('postgres_changes',{event:'*',schema:'public',table:'sale_returns'},reloadCurrent).subscribe()}
let reloadTimer;function reloadCurrent(){clearTimeout(reloadTimer);reloadTimer=setTimeout(async()=>{await refreshAll();route(state.current)},350)}

function completedSales(){return state.sales.filter(s=>['completed','partial_return'].includes(String(s.status||'').trim().toLowerCase()))}
function periodStats(days=30){const end=new Date(),start=new Date();start.setDate(end.getDate()-days+1);const sales=completedSales().filter(s=>new Date(s.created_at)>=start);const omzet=sales.reduce((a,s)=>a+num(s.net_total),0),hpp=sales.reduce((a,s)=>a+num(s.cogs_total),0),exp=state.expenses.filter(e=>new Date(e.expense_date)>=new Date(start.toISOString().slice(0,10))).reduce((a,e)=>a+num(e.amount),0);return{sales,omzet,hpp,gross:omzet-hpp,exp,net:omzet-hpp-exp}}
function renderDashboard(){const role=state.profile.role,today=todayISO(),todaySales=completedSales().filter(s=>new Date(s.created_at).toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'})===today),omzet=todaySales.reduce((a,s)=>a+num(s.net_total),0),hpp=todaySales.reduce((a,s)=>a+num(s.cogs_total),0),exp=state.expenses.filter(e=>e.expense_date===today).reduce((a,e)=>a+num(e.amount),0),stock=state.variants.reduce((a,v)=>a+num(v.stock_qty),0),low=state.variants.filter(v=>num(v.stock_qty)<=num(v.min_stock)).length,inventory=state.variants.reduce((a,v)=>a+num(v.stock_qty)*num(v.products?.cost_price),0),m=periodStats(30);$('#pageTitle').textContent=role==='owner'?'Dashboard Owner':role==='admin'?'Dashboard Admin':'Dashboard Kasir';$('#pageSubtitle').textContent='Data toko tersinkron realtime';let cards=role==='owner'?metric('Omzet Hari Ini',rupiah(omzet),'Transaksi selesai')+metric('Laba Kotor Hari Ini',rupiah(omzet-hpp),'Omzet - HPP')+metric('Laba Bersih Hari Ini',rupiah(omzet-hpp-exp),'Setelah pengeluaran',omzet-hpp-exp>=0?'kpi-good':'kpi-bad')+metric('Nilai Persediaan',rupiah(inventory),'Stok × harga modal'):role==='admin'?metric('Total Stok',stock+' pcs','Semua variasi')+metric('Stok Menipis',low+' variasi','Perlu perhatian')+metric('Penjualan Hari Ini',rupiah(omzet),'Realtime')+metric('Transaksi Hari Ini',todaySales.length,'Selesai'):metric('Penjualan Hari Ini',rupiah(omzet),'Realtime')+metric('Transaksi Saya',todaySales.filter(s=>s.cashier_id===state.user.id).length,'Hari ini')+metric('Barang Terjual',todaySales.reduce((a,s)=>a+num(s.item_count),0),'Hari ini')+metric('Stok Menipis',low+' variasi','Info stok');$('#content').innerHTML=`<div class="cards">${cards}</div>${role==='owner'?`<div class="grid2"><div class="card"><div class="section-title"><h3>Penjualan 14 Hari</h3></div><div class="chart-wrap"><canvas id="salesChart"></canvas></div></div><div class="card"><h3>Ringkasan 30 Hari</h3><div class="stat-list"><div class="stat-row"><span>Omzet</span><b>${rupiah(m.omzet)}</b></div><div class="stat-row"><span>HPP</span><b>${rupiah(m.hpp)}</b></div><div class="stat-row"><span>Laba Kotor</span><b>${rupiah(m.gross)}</b></div><div class="stat-row"><span>Pengeluaran</span><b>${rupiah(m.exp)}</b></div><div class="stat-row"><span>Laba Bersih</span><b>${rupiah(m.net)}</b></div><div class="stat-row"><span>Margin</span><b>${m.omzet?((m.net/m.omzet)*100).toFixed(1):0}%</b></div></div></div></div>`:''}<div class="grid2" style="margin-top:14px"><div class="card"><div class="section-title"><h3>Transaksi Terbaru</h3></div>${salesTable(state.sales.slice(0,8))}</div><div class="card"><div class="section-title"><h3>Stok Menipis</h3></div>${lowStockTable()}</div></div>`;if(role==='owner')drawSalesChart()}
function drawSalesChart(){const labels=[],vals=[];for(let i=13;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=d.toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'});labels.push(d.toLocaleDateString('id-ID',{day:'2-digit',month:'short'}));vals.push(completedSales().filter(s=>new Date(s.created_at).toLocaleDateString('en-CA',{timeZone:'Asia/Jakarta'})===key).reduce((a,s)=>a+num(s.net_total),0))}state.charts.push(new Chart($('#salesChart'),{type:'line',data:{labels,datasets:[{label:'Omzet',data:vals,tension:.3,fill:false}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>'Rp'+new Intl.NumberFormat('id-ID',{notation:'compact'}).format(v)}}}}}))}
function lowStockTable(){const rows=state.variants.filter(v=>num(v.stock_qty)<=num(v.min_stock)).slice(0,12);return rows.length?`<div class="table-wrap"><table class="table"><tr><th>Produk</th><th>Size</th><th>Warna</th><th>Stok</th></tr>${rows.map(v=>`<tr><td>${esc(v.products?.name)}</td><td>${esc(v.size)}</td><td>${esc(v.color)}</td><td><span class="badge ${v.stock_qty===0?'bad':'warn'}">${v.stock_qty}</span></td></tr>`).join('')}</table></div>`:'<div class="empty">Stok aman.</div>'}

function renderPOS(){$('#pageTitle').textContent='Kasir / POS';$('#pageSubtitle').textContent='Cari nama, SKU atau scan barcode';$('#content').innerHTML=`<div class="pos-grid"><div class="card"><div class="toolbar"><input id="productSearch" autofocus placeholder="Cari / scan barcode..."><select id="posBrand"><option value="">Semua brand</option>${[...new Set(state.products.map(p=>p.brands?.name).filter(Boolean))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div id="productGrid" class="product-grid"></div></div><div class="card"><div class="section-title"><h3>Keranjang</h3><button id="clearCart" class="danger-btn compact">Kosongkan</button></div><div id="cartLines"></div><div class="cart-total"><span>Total</span><span id="cartTotal">Rp0</span></div><button id="payBtn" class="primary full">Bayar (F4)</button></div></div>`;$('#productSearch').oninput=renderProductGrid;$('#posBrand').onchange=renderProductGrid;$('#clearCart').onclick=()=>{state.cart=[];renderCart()};$('#payBtn').onclick=openCheckout;document.onkeydown=e=>{if(state.current!=='pos')return;if(e.key==='F4'){e.preventDefault();openCheckout()}if(e.key==='F2'){e.preventDefault();$('#productSearch').focus()}};renderProductGrid();renderCart();setTimeout(()=>$('#productSearch')?.focus(),30)}
function renderProductGrid(){const q=($('#productSearch')?.value||'').toLowerCase(),brand=$('#posBrand')?.value||'';const arr=state.variants.filter(v=>num(v.stock_qty)>0&&`${v.products?.name} ${v.products?.sku} ${v.barcode} ${v.size} ${v.color}`.toLowerCase().includes(q)&&(!brand||state.products.find(p=>p.id===v.product_id)?.brands?.name===brand));$('#productGrid').innerHTML=arr.slice(0,100).map(v=>`<div class="product-card" data-id="${v.id}"><strong>${esc(v.products?.name)}</strong><span>${esc(v.color)} • Size ${esc(v.size)} • Stok ${v.stock_qty}</span><strong>${rupiah(v.products?.sale_price)}</strong></div>`).join('')||'<div class="empty">Produk tidak ditemukan.</div>';$$('.product-card').forEach(e=>e.onclick=()=>addCart(e.dataset.id));if(q&&arr.length===1&&arr[0].barcode===q){addCart(arr[0].id);$('#productSearch').value='';renderProductGrid()}}
function addCart(id){const v=state.variants.find(x=>x.id===id);if(!v)return;const ex=state.cart.find(x=>x.variant_id===id);if(ex){if(ex.qty>=v.stock_qty)return toast('Stok tidak cukup');ex.qty++}else state.cart.push({variant_id:id,name:v.products.name,size:v.size,color:v.color,price:num(v.products.sale_price),cost:num(v.products.cost_price),qty:1,max:num(v.stock_qty),barcode:v.barcode});renderCart()}
function renderCart(){if(!$('#cartLines'))return;$('#cartLines').innerHTML=state.cart.length?state.cart.map((x,i)=>`<div class="cart-line"><div><strong>${esc(x.name)}</strong><small>${esc(x.color)} • Size ${esc(x.size)} • ${rupiah(x.price)}</small><div class="qty-tools"><button class="ghost" data-minus="${i}">−</button><b>${x.qty}</b><button class="ghost" data-plus="${i}">+</button></div></div><div><strong>${rupiah(x.qty*x.price)}</strong><br><button class="danger-btn compact" data-remove="${i}">Hapus</button></div></div>`).join(''):'<div class="empty">Keranjang masih kosong.</div>';$$('[data-minus]').forEach(b=>b.onclick=()=>{const x=state.cart[b.dataset.minus];x.qty--;if(x.qty<=0)state.cart.splice(b.dataset.minus,1);renderCart()});$$('[data-plus]').forEach(b=>b.onclick=()=>{const x=state.cart[b.dataset.plus];if(x.qty<x.max)x.qty++;else toast('Stok tidak cukup');renderCart()});$$('[data-remove]').forEach(b=>b.onclick=()=>{state.cart.splice(b.dataset.remove,1);renderCart()});$('#cartTotal').textContent=rupiah(cartGross())}
const cartGross=()=>state.cart.reduce((a,x)=>a+x.qty*x.price,0);function openCheckout(){if(!state.cart.length)return toast('Keranjang kosong');$('#saleDiscount').value=0;$('#paidAmount').value=cartGross();$('#checkoutDialog').showModal();updateCheckout()}
function updateCheckout(){const gross=cartGross(),disc=Math.min(num($('#saleDiscount')?.value),gross),net=gross-disc,method=$('#paymentMethod')?.value,paid=method==='Tunai'?num($('#paidAmount')?.value):net;if(method!=='Tunai'&&$('#paidAmount'))$('#paidAmount').value=net;$('#checkoutSummary').innerHTML=`${state.cart.length} baris • ${state.cart.reduce((a,x)=>a+x.qty,0)} item • Subtotal <b>${rupiah(gross)}</b>`;$('#checkoutNet').textContent=rupiah(net);$('#changeAmount').textContent=rupiah(Math.max(0,paid-net))}
async function checkout(){
  if(!state.cart.length)return toast('Keranjang kosong');
  const btn=$('#confirmCheckout');
  if(btn?.disabled)return;

  const gross=cartGross();
  const discount=Math.min(num($('#saleDiscount').value),gross);
  const net=gross-discount;
  const method=$('#paymentMethod').value;
  const paid=method==='Tunai'?num($('#paidAmount').value):net;

  if(paid<net)return toast('Uang dibayar kurang');
  if(state.profile.role==='kasir'&&discount>num(state.settings.cashier_max_discount))
    return toast('Diskon melebihi batas kasir');

  // Validasi cepat terhadap stok yang sedang tampil.
  for(const x of state.cart){
    const v=state.variants.find(row=>row.id===x.variant_id);
    if(!v)return toast(`Varian ${x.name} tidak ditemukan`);
    if(num(v.stock_qty)<x.qty)return toast(`Stok ${x.name} tidak cukup`);
  }

  if(btn)btn.disabled=true;
  try{
    const openShift=state.shifts.find(s=>s.cashier_id===state.user.id&&s.status==='open');
    const items=state.cart.map(x=>({variant_id:x.variant_id,qty:x.qty}));

    const {data:sale,error}=await sb.rpc('create_sale_transaction',{
      p_shift_id:openShift?.id||null,
      p_customer_id:null,
      p_discount_total:discount,
      p_payment_method:method,
      p_paid_amount:paid,
      p_items:items
    });

    let savedSale=sale;
    if(error){
      console.error('create_sale_transaction:',error);
      // Kompatibilitas dengan database lama yang belum memiliki RPC v2.5.
      // Transaksi tetap disimpan melalui tabel lama; trigger database menangani stok.
      if(error.code==='PGRST202'||/create_sale_transaction|function .* does not exist/i.test(error.message||'')){
        const {data:legacySale,error:legacyError}=await sb.from('sales').insert({
          cashier_id:state.user.id,shift_id:openShift?.id||null,customer_id:null,
          gross_total:gross,discount_total:discount,net_total:net,cogs_total:state.cart.reduce((a,x)=>a+x.qty*x.cost,0),
          payment_method:method,paid_amount:paid,change_amount:Math.max(0,paid-net),
          item_count:state.cart.reduce((a,x)=>a+x.qty,0),status:'completed'
        }).select().single();
        if(legacyError)return toast('Penjualan gagal disimpan: '+legacyError.message);
        const {error:itemError}=await sb.from('sale_items').insert(state.cart.map(x=>({
          sale_id:legacySale.id,variant_id:x.variant_id,qty:x.qty,unit_price:x.price,unit_cost:x.cost,subtotal:x.qty*x.price
        })));
        if(itemError){
          await sb.from('sales').update({status:'void',void_reason:'Gagal menyimpan item: '+itemError.message}).eq('id',legacySale.id);
          return toast('Item penjualan gagal disimpan: '+itemError.message);
        }
        savedSale=legacySale;
      }else return toast(error.message||'Transaksi gagal disimpan');
    }

    await audit('CREATE_SALE','sales',savedSale.id,{invoice:savedSale.invoice_no,total:savedSale.net_total});
    const saved=[...state.cart];
    state.cart=[];
    $('#checkoutDialog').close();
    toast('Transaksi berhasil tersimpan');
    showReceipt(savedSale,saved);
    await refreshAll();
    if(state.current==='pos')renderPOS();
  }catch(e){
    console.error(e);
    toast(e?.message||'Terjadi kesalahan saat menyimpan transaksi');
  }finally{
    if(btn)btn.disabled=false;
  }
}
function openPrintWindow(title,html,kind='receipt'){
  const w=window.open('','_blank','width=520,height=720');
  if(!w){toast('Popup diblokir browser. Izinkan pop-up untuk mencetak.');return}
  const isReceipt=kind==='receipt';
  const width=isReceipt?'76mm':'60mm';
  w.document.open();
  w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>
    *{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff;color:#000;font-family:Arial,Helvetica,sans-serif}
    body{padding:4mm;margin:0 auto;width:${width};font-size:12px;line-height:1.35}
    .receipt{text-align:center;width:100%}.receipt h3{font-size:17px;margin:0 0 4px}.receipt>small{display:block;margin-bottom:8px}
    .receipt-items{border-top:1px dashed #000;border-bottom:1px dashed #000;padding:8px 0;margin:8px 0;text-align:left}
    .receipt-row{display:flex;justify-content:space-between;gap:10px;text-align:left;margin:3px 0}.receipt-row span:last-child,.receipt-row b:last-child{text-align:right}
    .receipt p{margin:10px 0 0;text-align:center}.barcode-label{text-align:center;width:100%}.barcode-label svg,.barcode-label img{max-width:100%;height:auto}
    @page{margin:3mm} @media print{html,body{width:auto}body{padding:0;margin:0 auto}}
  </style></head><body>${html}<script>window.onload=()=>{setTimeout(()=>window.print(),150)};<\/script></body></html>`);
  w.document.close();
}
